export const AGENT_CARD_COUNT = agentCards.length;

const ONES = [
  "Zero",
  "One",
  "Two",
  "Three",
  "Four",
  "Five",
  "Six",
  "Seven",
  "Eight",
  "Nine",
  "Ten",
  "Eleven",
  "Twelve",
  "Thirteen",
  "Fourteen",
  "Fifteen",
  "Sixteen",
  "Seventeen",
  "Eighteen",
  "Nineteen"
];

const TENS = [
  "",
  "",
  "Twenty",
  "Thirty",
  "Forty",
  "Fifty",
  "Sixty",
  "Seventy",
  "Eighty",
  "Ninety"
];

/**
 * Deterministic, dependency-free integer-to-English-word helper covering
 * 0-120 (tens + ones, hyphenated like "Fifty-one"). Pure: no clock, no
 * randomness. The leading letter is capitalized.
 */
export function integerToEnglishWord(n: number): string {
  if (!Number.isInteger(n) || n < 0 || n > 120) {
    throw new RangeError(
      `integerToEnglishWord supports integers 0-120, received ${n}`
    );
  }
  const words = (value: number): string => {
    if (value < 20) return ONES[value];
    if (value < 100) {
      const tens = TENS[Math.floor(value / 10)];
      const ones = value % 10;
      return ones === 0 ? tens : `${tens}-${ONES[ones].toLowerCase()}`;
    }
    const remainder = value - 100;
    return remainder === 0
      ? "One hundred"
      : `One hundred ${words(remainder).toLowerCase()}`;
  };
  return words(n);
}

export const AGENT_CARD_COUNT_WORD: string =
  integerToEnglishWord(AGENT_CARD_COUNT);
